import pandas as pd
from dataretrieval import nwis
import time

# Read station IDs
with open('/root/data/michigan_stations.txt') as f:
    station_ids = [line.strip() for line in f if line.strip()]

print(f"Total stations to download: {len(station_ids)}")

all_frames = []

for i, site_id in enumerate(station_ids):
    try:
        df, meta = nwis.get_iv(
            sites=site_id,
            start='2025-04-01',
            end='2025-04-07',
            parameterCd='00065'
        )
        if len(df) > 0:
            gage_col = [c for c in df.columns if '00065' in str(c) and '_cd' not in str(c)]
            if gage_col:
                result = df[[gage_col[0], 'site_no']].copy()
                result.columns = ['gage_height', 'site_no']
                result.index.name = 'datetime'
                all_frames.append(result)
                print(f"[{i+1}/{len(station_ids)}] {site_id}: {len(df)} records")
            else:
                print(f"[{i+1}/{len(station_ids)}] {site_id}: no gage height column")
        else:
            print(f"[{i+1}/{len(station_ids)}] {site_id}: no data")
    except Exception as e:
        print(f"[{i+1}/{len(station_ids)}] {site_id}: ERROR - {e}")

    if (i + 1) % 10 == 0:
        time.sleep(1)

if all_frames:
    combined = pd.concat(all_frames)
    combined.to_csv('/root/data/usgs_water_levels.csv')
    print(f"\nSaved {len(combined)} total records for {combined['site_no'].nunique()} stations")
else:
    print("No data downloaded!")

